WITH event_rows AS (SELECT mktcode,tgtcode,bizdate,ma3>ma30 AND LAG(ma3) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate)<=LAG(ma30) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate) AS matched FROM `newzl`.`hsj_stock_hq_basic_technical`), qualified AS (SELECT mktcode,tgtcode FROM event_rows WHERE bizdate>=DATE_TRUNC('2026-04-14','YEAR') AND bizdate<='2026-04-14' GROUP BY mktcode,tgtcode HAVING SUM(CASE WHEN matched THEN 1 ELSE 0 END)>0) SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` b JOIN qualified q ON q.mktcode=b.mktcode AND q.tgtcode=b.tgtcode WHERE b.bizdate='2026-04-14';
